do $$begin if not exists(select 1 from pg_roles where rolname='anon') then create role anon nologin;end if;if not exists(select 1 from pg_roles where rolname='authenticated') then create role authenticated nologin;end if;end$$;create schema auth;create schema solar_private;create function auth.uid() returns uuid language sql stable as $$select nullif(current_setting('request.jwt.claim.sub',true),'')::uuid$$;grant usage on schema public,auth,solar_private to authenticated,anon;
create table public.brands("id" int8 not null primary key,"name" text not null,"created_at" timestamptz default now() not null);
create table public.customers("id" int8 not null primary key,"name" text not null,"phone" text,"customer_type" text not null,"active" bool default true not null,"created_at" timestamptz default now() not null,"owner_id" uuid);
create table public.products("id" int8 not null primary key,"code" text not null,"name" text not null,"brand_id" int8,"category" text,"qty" numeric default 0 not null,"cost" numeric default 0 not null,"created_at" timestamptz default now() not null,"updated_at" timestamptz default now() not null);
create table public.profiles("id" uuid not null primary key,"display_name" text,"is_admin" bool default false not null,"active" bool default true not null,"permissions" jsonb default '{}'::jsonb not null,"created_at" timestamptz default now() not null,"updated_at" timestamptz default now() not null,"username" text,"role" text default 'user'::text not null,"user_type" text default 'admin_staff'::text not null);
create table public.solar_cash_entries("id" uuid default gen_random_uuid() not null primary key,"owner_id" uuid,"delta" numeric not null,"entry_type" text not null,"job_id" int8,"transfer_id" uuid,"actor_id" uuid not null,"notes" text default ''::text not null,"created_at" timestamptz default now() not null);
create table public.suppliers("id" int8 not null primary key,"name" text not null,"phone" text,"active" bool default true not null,"created_at" timestamptz default now() not null);
create table public.transaction_items("id" int8 generated by default as identity not null primary key,"transaction_id" int8 not null,"product_id" int8,"product_name" text not null,"brand_name" text,"category" text,"qty" numeric default 0 not null,"price" numeric default 0 not null,"cost" numeric default 0 not null,"landed_cost" numeric default 0 not null);
create table public.transactions("id" int8 not null primary key,"kind" text not null,"party_type" text,"party_id" int8,"party_name" text,"payment_mode" text,"subtotal" numeric default 0 not null,"expenses" numeric default 0 not null,"total" numeric default 0 not null,"cost" numeric default 0 not null,"profit" numeric default 0 not null,"notes" text,"cash" bool default false not null,"created_at" timestamptz default now() not null,"created_by" uuid,"cashbox_user_id" uuid,"capital_effect" bool default false not null,"installer_id" uuid,"install_date" date,"install_time" time,"customer_phone" text,"customer_address" text,"installation_status" text default 'none'::text not null,"installation_completed_at" timestamptz,"installation_closed_at" timestamptz,"installation_expenses" numeric default 0 not null,"installation_expense_notes" text,"installation_started_at" timestamptz,"installation_report" jsonb default '{}'::jsonb not null,"installation_revision" int8 default 0 not null,"receipt_no" int8 not null,"warehouse_status" text default 'pending'::text not null,"warehouse_revision" int8 default 0 not null,"warehouse_prepared_at" timestamptz,"warehouse_prepared_by" uuid,"warehouse_note" text default ''::text not null);
alter table public.transaction_items add foreign key(transaction_id) references public.transactions(id) on delete cascade;create table public.cash_ledger(transaction_id bigint references public.transactions(id) on delete cascade);create table solar_private.receipt_counters(kind text primary key,last_number bigint);create table solar_private.reset_record_ids(table_name text,record_id bigint);create table solar_private.deleted_sales(invoice_id bigint primary key,invoice jsonb,items jsonb,deleted_by uuid,deleted_at timestamptz default now());
CREATE OR REPLACE FUNCTION solar_private.guard_installation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
 if current_user in ('authenticated','anon') then
  if tg_op='INSERT' and new.kind='system' then
   if new.installation_status is distinct from 'pending' or new.installation_revision<>0 or new.installation_report<>'{}'::jsonb or coalesce(new.installation_expenses,0)<>0 or new.installation_completed_at is not null or new.installation_closed_at is not null or new.installation_started_at is not null then raise exception 'Invalid initial installation state'; end if;
  elsif tg_op='UPDATE' and (old.kind='system' or new.kind='system') then
   if (new.kind,new.installation_status,new.installation_revision,new.installation_report,new.installation_expenses,new.installation_expense_notes,new.installation_started_at,new.installation_completed_at,new.installation_closed_at) is distinct from (old.kind,old.installation_status,old.installation_revision,old.installation_report,old.installation_expenses,old.installation_expense_notes,old.installation_started_at,old.installation_completed_at,old.installation_closed_at) then raise exception 'Use installation workflow'; end if;
  end if;
 end if;
 return new;
end $function$;

CREATE OR REPLACE FUNCTION solar_private.lock_cash_writes()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin perform pg_advisory_xact_lock(7311,1);return null;end $function$;

CREATE OR REPLACE FUNCTION solar_private.guard_sale_delete()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
 if tg_op='UPDATE' then
  if current_user in ('authenticated','anon') and new.kind is distinct from old.kind then raise exception 'Invoice kind is immutable' using errcode='42501';end if;
  return new;
 end if;
 if current_user in ('authenticated','anon') and old.kind in ('sale','system') then raise exception 'Use authorized invoice deletion' using errcode='42501';end if;
 return old;
end $function$;

CREATE OR REPLACE FUNCTION solar_private.guard_deleted_sale_id()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if exists(select 1 from solar_private.deleted_sales where invoice_id=new.id) then raise exception 'Deleted invoice cannot be recreated' using errcode='40001';end if;
 return new;
end $function$;

CREATE OR REPLACE FUNCTION solar_private.guard_supplier_payment()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
 if current_user in ('anon','authenticated') and ((tg_op<>'INSERT' and old.kind='supplier_payment') or (tg_op<>'DELETE' and new.kind='supplier_payment')) then
  raise exception 'Use supplier payment action' using errcode='42501';
 end if;
 if tg_op='DELETE' then return old;end if;return new;
end $function$;

CREATE OR REPLACE FUNCTION solar_private.assign_receipt_number()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare existing bigint;
begin
 perform pg_advisory_xact_lock(7311,1);
 if tg_op='UPDATE' then new.receipt_no:=old.receipt_no;return new;end if;
 select receipt_no into existing from public.transactions where id=new.id;
 if existing is not null then new.receipt_no:=existing;return new;end if;
 insert into solar_private.receipt_counters(kind,last_number) values(new.kind,1)
 on conflict(kind) do update set last_number=solar_private.receipt_counters.last_number+1
 returning last_number into new.receipt_no;
 return new;
end $function$;

CREATE OR REPLACE FUNCTION solar_private.guard_reset_records()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if exists(select 1 from solar_private.reset_record_ids where table_name=tg_table_name and record_id=new.id) then
 raise exception 'Old data was reset. Refresh the application before saving.' using errcode='40001';end if;
 return new;
end $function$;

CREATE OR REPLACE FUNCTION solar_private.warehouse_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
 if current_user in ('authenticated','anon') then
  if tg_op='INSERT' and (new.warehouse_status<>'pending' or new.warehouse_revision<>0 or new.warehouse_prepared_at is not null or new.warehouse_prepared_by is not null or new.warehouse_note<>'') then raise exception 'Use warehouse workflow' using errcode='42501';end if;
  if tg_op='UPDATE' and (new.warehouse_status,new.warehouse_revision,new.warehouse_prepared_at,new.warehouse_prepared_by,new.warehouse_note) is distinct from (old.warehouse_status,old.warehouse_revision,old.warehouse_prepared_at,old.warehouse_prepared_by,old.warehouse_note) then raise exception 'Use warehouse workflow' using errcode='42501';end if;
 end if;
 return new;
end $function$;

CREATE OR REPLACE FUNCTION solar_private.warehouse_items_changed()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 update public.transactions set warehouse_status='pending',warehouse_prepared_at=null,warehouse_prepared_by=null,warehouse_revision=warehouse_revision+1
 where id=coalesce(new.transaction_id,old.transaction_id) and kind in ('sale','system') and warehouse_status='ready';
 return null;
end $function$;

CREATE OR REPLACE FUNCTION solar_private.guard_reconciliation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
 if current_user in ('anon','authenticated') and
 ((tg_op<>'INSERT' and old.payment_mode in ('opening_balance','account_reconciliation')) or
 (tg_op<>'DELETE' and new.payment_mode in ('opening_balance','account_reconciliation'))) then
  raise exception 'استخدم إجراء الرصيد الافتتاحي أو مطابقة الحساب' using errcode='42501';
 end if;
 if tg_op='DELETE' then return old;end if;return new;
end $function$;

CREATE TRIGGER solar_products_write_lock BEFORE INSERT OR DELETE OR UPDATE ON public.products FOR EACH STATEMENT EXECUTE FUNCTION solar_private.lock_cash_writes();
CREATE TRIGGER solar_reset_record_guard BEFORE INSERT OR UPDATE ON public.products FOR EACH ROW EXECUTE FUNCTION solar_private.guard_reset_records();
CREATE TRIGGER solar_assign_receipt BEFORE INSERT OR UPDATE ON public.transactions FOR EACH ROW EXECUTE FUNCTION solar_private.assign_receipt_number();
CREATE TRIGGER solar_cash_write_lock BEFORE INSERT OR DELETE OR UPDATE ON public.transactions FOR EACH STATEMENT EXECUTE FUNCTION solar_private.lock_cash_writes();
CREATE TRIGGER solar_guard_deleted_sale_id BEFORE INSERT ON public.transactions FOR EACH ROW EXECUTE FUNCTION solar_private.guard_deleted_sale_id();
CREATE TRIGGER solar_guard_sale_delete BEFORE DELETE OR UPDATE ON public.transactions FOR EACH ROW EXECUTE FUNCTION solar_private.guard_sale_delete();
CREATE TRIGGER solar_guard_supplier_payment BEFORE INSERT OR DELETE OR UPDATE ON public.transactions FOR EACH ROW EXECUTE FUNCTION solar_private.guard_supplier_payment();
CREATE TRIGGER solar_installation_guard BEFORE INSERT OR UPDATE ON public.transactions FOR EACH ROW EXECUTE FUNCTION solar_private.guard_installation();
CREATE TRIGGER solar_reconciliation_guard BEFORE INSERT OR DELETE OR UPDATE ON public.transactions FOR EACH ROW EXECUTE FUNCTION solar_private.guard_reconciliation();
CREATE TRIGGER solar_reset_record_guard BEFORE INSERT OR UPDATE ON public.transactions FOR EACH ROW EXECUTE FUNCTION solar_private.guard_reset_records();
CREATE TRIGGER solar_warehouse_guard BEFORE INSERT OR UPDATE ON public.transactions FOR EACH ROW EXECUTE FUNCTION solar_private.warehouse_guard();
CREATE TRIGGER solar_items_write_lock BEFORE INSERT OR DELETE OR UPDATE ON public.transaction_items FOR EACH STATEMENT EXECUTE FUNCTION solar_private.lock_cash_writes();
CREATE TRIGGER solar_warehouse_items_changed AFTER INSERT OR DELETE OR UPDATE ON public.transaction_items FOR EACH ROW EXECUTE FUNCTION solar_private.warehouse_items_changed();
create function solar_private.cash_balance(uid uuid) returns numeric language sql stable security definer set search_path='' as $$select coalesce((select sum(case when t.kind in ('purchase','supplier_payment','cash_expense','profit_distribution') then -t.total else t.total end) from public.transactions t where t.cash and coalesce(t.cashbox_user_id,t.created_by)=uid),0)+coalesce((select sum(e.delta) from public.solar_cash_entries e where e.owner_id=uid),0)$$;grant all on all tables in schema public to authenticated;grant usage,select on all sequences in schema public to authenticated;CREATE OR REPLACE FUNCTION solar_private.can_delete_sale(owner_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
 select exists(select 1 from public.profiles p where p.id=auth.uid() and p.active and p.user_type<>'installer'
 and (p.is_admin or p.permissions->>'salesDeleteAll'='true' or (p.permissions->>'salesDeleteOwn'='true' and p.id=owner_id)))
$function$
;
CREATE OR REPLACE FUNCTION solar_private.sale_delete(invoice_id bigint, expected_token text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare t public.transactions; preview jsonb; line_data jsonb; archived jsonb; nid uuid; target uuid;
begin
 if solar_private.role_name()='warehouse' then raise exception 'Not permitted' using errcode='42501';end if;
 perform pg_advisory_xact_lock(7311,1);
 select * into t from public.transactions where id=invoice_id and kind in ('sale','system') for update;
 if t.id is null then
  select invoice into archived from solar_private.deleted_sales d where d.invoice_id=sale_delete.invoice_id;
  if archived is not null and solar_private.can_delete_sale((archived->>'created_by')::uuid) then return;end if;
  raise exception 'Not permitted' using errcode='42501';
 end if;
 preview:=solar_private.sale_delete_data(t.id);
 if preview->>'token' is distinct from expected_token then raise exception 'Invoice changed' using errcode='40001';end if;
 if preview->>'blockedReason' is not null then raise exception '%',preview->>'blockedReason';end if;
 select coalesce(jsonb_agg(to_jsonb(i) order by i.id),'[]') into line_data from public.transaction_items i where i.transaction_id=t.id;
 insert into solar_private.deleted_sales(invoice_id,invoice,items,deleted_by) values(t.id,to_jsonb(t),line_data,auth.uid());
 update public.products p set qty=coalesce(p.qty,0)+x.qty from (select i.product_id,sum(i.qty) qty from public.transaction_items i where i.transaction_id=t.id group by i.product_id) x where p.id=x.product_id;
 delete from public.cash_ledger where transaction_id=t.id;
 delete from public.transactions where id=t.id;
 -- An engineer must not keep travelling to a deleted assignment.
 for target in select distinct x from unnest(array[t.installer_id,t.created_by]) x where x is not null and x<>auth.uid() loop
  if exists(select 1 from public.profiles p where p.id=target and p.active) then
   insert into public.solar_notifications(user_id,event,title,body) values(target,'invoice_deleted','تم حذف فاتورة مرتبطة بك','تم حذف الفاتورة #'||t.id::text||' وإلغاء تكليف التنصيب المرتبط بها إن وجد.') returning id into nid;
   insert into solar_private.push_deliveries(notification_id,endpoint) select nid,s.endpoint from public.solar_push_subscriptions s where s.user_id=target;
  end if;
 end loop;
 perform solar_private.wake_push();
end $function$
;
CREATE OR REPLACE FUNCTION solar_private.sale_delete_data(invoice_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare t public.transactions; line_data jsonb; blocked text;
begin
 if solar_private.role_name()='warehouse' then raise exception 'Not permitted' using errcode='42501';end if;
 select * into t from public.transactions where id=invoice_id and kind in ('sale','system');
 if t.id is null or not solar_private.can_delete_sale(t.created_by) then raise exception 'Not permitted' using errcode='42501';end if;
 select coalesce(jsonb_agg(to_jsonb(i) order by i.id),'[]') into line_data from public.transaction_items i where i.transaction_id=t.id;
 if exists(select 1 from public.solar_cash_entries where job_id=t.id) or coalesce(t.installation_expenses,0)>0 then
  blocked:='لا يمكن حذف فاتورة مرتبطة بمصاريف تنصيب معتمدة أو مدفوعة؛ يجب معالجة مصاريفها محاسبياً أولاً.';
 elsif exists(select 1 from public.transaction_items i where i.transaction_id=t.id and (i.product_id is null or i.qty is null or i.qty<=0)) then
  blocked:='لا يمكن حذف الفاتورة لوجود مادة محذوفة أو كمية غير صحيحة؛ راجع المواد أولاً.';
 elsif t.cash and t.total>0 and solar_private.cash_balance(coalesce(t.cashbox_user_id,t.created_by))<t.total then
  blocked:='لا يمكن حذف الوصل النقدي لأن رصيد قاصة صاحبه لا يكفي لإلغاء المبلغ؛ سوِّ القاصة أولاً.';
 end if;
 return jsonb_build_object('receiptNo',t.receipt_no,'token',md5(to_jsonb(t)::text||line_data::text),'party',t.party_name,'total',t.total,'kind',t.kind,'blockedReason',blocked);
end $function$
;
-- Notification dispatch is unrelated to these isolated pricing tests.
create function solar_private.wake_push() returns void language plpgsql as $$begin return;end$$;
create function public.solar_sale_delete_preview(invoice_id bigint) returns jsonb language sql security invoker as $$select solar_private.sale_delete_data(invoice_id)$$;
grant execute on function solar_private.sale_delete_data(bigint),solar_private.can_delete_sale(uuid),public.solar_sale_delete_preview(bigint) to authenticated;

create function solar_private.role_name() returns text language sql stable security definer set search_path='' as $$select case when p.user_type='installer' then 'installer' when p.user_type='warehouse' then 'warehouse' when p.is_admin then 'admin' else 'staff' end from public.profiles p where p.id=auth.uid() and p.active$$;
